    /** @return array{title: string, body: string} */
    public static function notice(string $audience, string $company): array
    {
        $label = [
            'employee' => 'พนักงาน', 'applicant' => 'ผู้สมัครงาน', 'visitor' => 'ผู้มาติดต่อ', 'complainant' => 'ผู้ร้องเรียน',
            'gps' => 'พนักงานที่ลงเวลาด้วยตำแหน่ง (GPS)', 'contractor' => 'ผู้รับเหมาและพนักงานผู้รับเหมา', 'customer' => 'ลูกค้าและคู่ค้า', 'general' => 'บุคคลทั่วไป',
        ][$audience] ?? 'บุคคลทั่วไป';
        $body = "{$company} (\"บริษัท\") ให้ความสำคัญกับข้อมูลส่วนบุคคลของ{$label} ประกาศนี้อธิบายว่าบริษัทเก็บข้อมูลใด เพื่ออะไร ใครเห็น เก็บนานแค่ไหน และท่านมีสิทธิอะไร\n\n"
            . "1. ผู้ควบคุมข้อมูลและช่องทางติดต่อ\n{$company} · [[ที่อยู่]] · ช่องทางติดต่อเรื่องข้อมูลส่วนบุคคล: [[อีเมล/โทรศัพท์ของผู้ดูแลความเป็นส่วนตัว]]\n\n"
            . "2. ข้อมูลที่เก็บ\n" . (self::DATA[$audience] ?? self::DATA['general']) . "\n\n"
            . "3. วัตถุประสงค์และฐานทางกฎหมาย\n" . (self::PURPOSE[$audience] ?? self::PURPOSE['general']) . "\nฐานทางกฎหมายของแต่ละวัตถุประสงค์: [[ให้ผู้มีความรู้ด้านกฎหมายระบุ]]\n\n"
            . "4. ผู้ที่ได้รับข้อมูล\nเฉพาะผู้ที่มีหน้าที่เกี่ยวข้องภายในบริษัท ตามสิทธิ์ที่กำหนดในระบบ และหน่วยงานหรือผู้ให้บริการภายนอกเท่าที่จำเป็น ได้แก่ [[รายชื่อผู้ให้บริการ/หน่วยงาน]]\n\n"
            . "5. ระยะเวลาเก็บ\n[[ระยะเก็บตามกฎระยะเก็บที่บริษัทอนุมัติ]] เมื่อครบกำหนดบริษัทจะลบหรือทำให้ไม่สามารถระบุตัวท่านได้\n\n"
            . "6. สิทธิของท่าน\nท่านขอเข้าถึงหรือขอสำเนา ขอแก้ไข ขอลบ ขอคัดค้าน ขอระงับการใช้ ขอโอนย้ายข้อมูล และถอนความยินยอม (ถ้าบริษัทใช้ความยินยอม) ได้ ตามเงื่อนไขของกฎหมาย"
            . ($audience === 'employee' || $audience === 'gps' ? ' — พนักงานยื่นคำขอได้ที่เมนู "ข้อมูลส่วนบุคคลของฉัน"' : '') . " และร้องเรียนต่อหน่วยงานกำกับดูแลได้\n\n"
            . "7. การรักษาความปลอดภัย\nบริษัทจำกัดสิทธิ์การเข้าถึงตามหน้าที่ เข้ารหัสข้อมูลที่อ่อนไหว และบันทึกการเข้าถึงข้อมูลสำคัญ\n\n"
            . "8. การเปลี่ยนแปลงประกาศ\nบริษัทอาจปรับปรุงประกาศนี้ ฉบับล่าสุดแสดงเลขฉบับและวันที่มีผลไว้ด้านบน";
        return ['title' => 'ประกาศความเป็นส่วนตัวสำหรับ' . $label, 'body' => $body];
    }

